export const HISTORY_KEY = 'emi-calc.v1.history'
export const SETTINGS_KEY = 'emi-calc.v1.settings'

// ---------------------------------------------------------------------------
// Reference loans (docs/user-stories.md "Reference loans used in the criteria").
// ---------------------------------------------------------------------------
export interface Loan {
